	/**
	 * この画面のステータスを設定します。
	 *
	 * @param status ステータス
	 */
	public void setStatus(String status) {
		super.setStatus(status);
		if (INST_INS.equals(status)) {
			setINST_INSStatus();
		}
		else if (ACT_INS.equals(status)) {
			setACT_INSStatus();
		}
		else if (UPD.equals(status)) {
			setUPDStatus();
		}
		else if (INST_PRNT.equals(status)) {
			setINST_PRNTStatus();
		}
		else if (INST_PRNT_DLV.equals(status)) {
			setINST_PRNT_DLVStatus();
		}
		else if (ACT_PRNT.equals(status)) {
			setACT_PRNTStatus();
		}
		else if (ACT_PRNT_DLV.equals(status)) {
			setACT_PRNT_DLVStatus();
		}
		else if (INST_DEL.equals(status)) {
			setINST_DELStatus();
		}
		else if (ACT_DEL.equals(status)) {
			setACT_DELStatus();
		}
		else if (REF.equals(status)) {
			setREFStatus();
		}
		else if (ACT_REF.equals(status)) {
			setACT_REFStatus();
		}
		else if (ACT_REF_HDR.equals(status)) {
			setACT_REF_HDRStatus();
		}
	}

