	/**
	 * リストを保持する画面部品のリストを返します。
	 */
	public MCList getList(MCEventBeans combo, MCRow row, MCEventInfo info) {
		MCList list = super.getList(combo, row, info);
		if(list != null) return list;
		if(combo == Cnd_wg_cd) return getCnd_wg_cd(row, info);
		if(combo == Cnd_lg_grp_cd) return getCnd_lg_grp_cd(row, info);
		if(combo == Cnd_gi_loc_cd) return getCnd_gi_loc_cd(row, info);
		if(combo == Cnd_gi_str_ln_cd) return getCnd_gi_str_ln_cd(row, info);
		if(combo == Cnd_gi_site_cd) return getCnd_gi_site_cd(row, info);
		if(combo == Cnd_gi_stk_arrv_bp_cd) return getCnd_gi_stk_arrv_bp_cd(row, info);
		if(combo == Cnd_gr_loc_cd) return getCnd_gr_loc_cd(row, info);
		if(combo == Cnd_gr_str_ln_cd) return getCnd_gr_str_ln_cd(row, info);
		if(combo == Cnd_gr_site_cd) return getCnd_gr_site_cd(row, info);
		if(combo == Cnd_gr_stk_arrv_bp_cd) return getCnd_gr_stk_arrv_bp_cd(row, info);
		if(combo == Cnd_trd_unit_cd) return getCnd_trd_unit_cd(row, info);
		if(combo == Cnd_base_unit_cd) return getCnd_base_unit_cd(row, info);
		if(combo == Cnd_pckg_unit_cd) return getCnd_pckg_unit_cd(row, info);
		if(combo == Cnd_gd_cd) return getCnd_gd_cd(row, info);
		if(combo == Cnd_quality_typ) return getCnd_quality_typ(row, info);
		if(combo == Cnd_stk_insp_typ) return getCnd_stk_insp_typ(row, info);
		if(combo == Cnd_stk_id_typ) return getCnd_stk_id_typ(row, info);
		if(combo == Cnd_stk_bp_cd) return getCnd_stk_bp_cd(row, info);
		if(combo == Cnd_rqst_usr_cd) return getCnd_rqst_usr_cd(row, info);
		if(combo == Cnd_rqst_dpt_cd) return getCnd_rqst_dpt_cd(row, info);
		if(combo == Cnd_inst_usr_cd) return getCnd_inst_usr_cd(row, info);
		if(combo == Cnd_inst_dpt_cd) return getCnd_inst_dpt_cd(row, info);
		if(combo == Cnd_act_usr_cd) return getCnd_act_usr_cd(row, info);
		if(combo == Cnd_act_dpt_cd) return getCnd_act_dpt_cd(row, info);
		if(combo == Cnd_ship_inst_typ) return getCnd_ship_inst_typ(row, info);
		if(combo == Cnd_rsn_cd) return getCnd_rsn_cd(row, info);
		if(combo == Cnd_bd_dpt_cd) return getCnd_bd_dpt_cd(row, info);
		if(combo == Cnd_trd_cd) return getCnd_trd_cd(row, info);
		if(combo == Cnd_xfr_src_typ) return getCnd_xfr_src_typ(row, info);
		if(combo == BulkSet_inst_usr_dpt_p_PPanel.UsrDpt_dpt_cd) return getBulkSet_inst_usr_dpt_p_PPanel_UsrDpt_dpt_cd(row, info);
		if(combo == BulkSet_act_usr_dpt_p_PPanel.UsrDpt_dpt_cd) return getBulkSet_act_usr_dpt_p_PPanel_UsrDpt_dpt_cd(row, info);
		if(combo == columnRslt_trd_unit_cd) return getRslt_trd_unit_cd(row, info);
		return null;
	}

	/**
	 * ActionPerformedイベントが実行されたときに呼び出されます。
	 *
	 * @param ap ActionPerformedイベントが実行されたGUI部品
	 */
	public void doAPEvent(MCAPBeans ap, MCEventInfo info) {
		super.doAPEvent(ap, info);
		if (ap == Ctrl_ctrl_PPanel.Ope_srch) doCtrl_ctrl_Ope_srch(info);
		else if (ap == RPnl_dwnld) doRPnl_dwnld(info);
		else if (ap == Btn_open_MSBEP1010) doBtn_open_MSBEP1010(info);
		else if (ap == Btn_open_MSBEP1020) doBtn_open_MSBEP1020(info);
		else if (ap == Btn_open_MSBEP0060) doBtn_open_MSBEP0060(info);
		else if (ap == Btn_prnt_pick) doBtn_prnt_pick(info);
		else if (ap == Btn_prnt_inst) doBtn_prnt_inst(info);
		else if (ap == Btn_prnt_dlv) doBtn_prnt_dlv(info);
		else if (ap == Btn_alloc) doBtn_alloc(info);
		else if (ap == Btn_release_alloc) doBtn_release_alloc(info);
		else if (ap == Btn_select_all) doBtn_select_all(info);
		else if (ap == Btn_deselect_all) doBtn_deselect_all(info);
		else if (ap == Btn_pack_select_all) doBtn_pack_select_all(info);
		else if (ap == Btn_pack_deselect_all) doBtn_pack_deselect_all(info);
		else if (ap == Btn_rdel) doBtn_rdel(info);
		else if (ap == Btn_rcopy) doBtn_rcopy(info);
		else if (ap == Btn_upd_inst) doBtn_upd_inst(info);
		else if (ap == Btn_upd_act) doBtn_upd_act(info);
		else if (ap == Btn_upd_schd) doBtn_upd_schd(info);
		else if (ap == Btn_del_inst) doBtn_del_inst(info);
		else if (ap == Btn_del_act) doBtn_del_act(info);
	}

